<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import {writingLibrary,type PersonalWriting} from '@/api/writing'
import {useAuthStore} from '@/stores/auth'
import {onRemoteIdentityChange,getGeneration} from '@/auth/token-session'
import {errorMessage} from '@/api/identity'
import WritingMaterialDetail from '@/components/reading/WritingMaterialDetail.vue'
const auth=useAuthStore(),view=ref('favorites'),page=ref(1),items=ref<PersonalWriting[]>([]),total=ref(0),busy=ref(false),error=ref(''),selected=ref<string>()
let controller:AbortController|undefined,generation=0
async function load(){const ticket=++generation,identity=getGeneration();controller?.abort();controller=new AbortController();busy.value=true;error.value='';items.value=[];if(!auth.user){busy.value=false;return}try{const data=await writingLibrary(view.value,page.value,controller.signal);if(ticket!==generation||identity!==getGeneration())return;items.value=data.items;total.value=data.total;if(!data.items.length&&page.value>1){page.value--;return}}catch(e){if(ticket===generation&&identity===getGeneration()&&!(e instanceof DOMException&&e.name==='AbortError'))error.value=errorMessage(e)}finally{if(ticket===generation)busy.value=false}}
function clear(){generation++;controller?.abort();items.value=[];total.value=0;selected.value=undefined;busy.value=false}
const unsubscribe=onRemoteIdentityChange(clear)
watch(view,()=>{page.value=1;void load()});watch(page,load);watch(()=>auth.user?.id,()=>{clear();void load()},{immediate:true,flush:'sync'})
onBeforeUnmount(()=>{clear();unsubscribe()})
</script>
<template><section class="reading-page writing-library"><header class="reading-page-header"><div><h1>我的写作素材</h1><p>收藏值得再用的表达，也留下自己的那一句。</p></div><RouterLink class="button-secondary" to="/reading">去阅读</RouterLink></header><div class="writing-library-tabs" role="group" aria-label="素材库筛选"><button type="button" :aria-pressed="view==='favorites'" @click="view='favorites'">我的收藏</button><button type="button" :aria-pressed="view==='imitations'" @click="view='imitations'">我的仿写</button></div><p v-if="busy" class="reading-empty" role="status">正在加载写作素材…</p><div v-else-if="error" class="reading-notice" role="alert"><p>{{ error }}</p><button type="button" class="button-secondary" @click="load">重试素材库</button></div><div v-else-if="!items.length" class="reading-empty"><h2>{{ view==='favorites'?'还没有收藏写作素材':'还没有保存仿写' }}</h2><p>阅读文章时展开写作积累，留下一个想再次使用的表达。</p></div><div v-else class="writing-library-grid"><article v-for="item in items" :key="item.materialId" class="writing-library-card"><span v-if="!item.available" class="reader-saved-badge">已下架或暂不可访问</span><h2 lang="en">{{ item.expression }}</h2><p>{{ item.material?.content.meaningZh||item.imitation?.snapshot.meaningZh }}</p><p v-if="item.imitation" class="writing-library-imitation" lang="en">{{ item.imitation.text }}</p><button type="button" class="button-secondary" @click="selected=item.materialId">查看素材</button></article></div><nav v-if="total>12" class="reading-pagination" aria-label="写作素材分页"><button class="button-secondary" :disabled="busy||page<=1" @click="page--">上一页</button><span>第 {{ page }} 页 · 共 {{ total }} 条</span><button class="button-secondary" :disabled="busy||page*12>=total" @click="page++">下一页</button></nav><WritingMaterialDetail v-if="selected" :key="selected" :material-id="selected" @close="selected=undefined" @changed="load" /></section></template>
